function varargout = calDTS(varargin)
% CALDTS MATLAB code for calDTS.fig
%
%   --- calDTS GUI  ---
%
% DESCRIPTION:
%   calDTS is a GUI for calibrating DTS MAT-files generated by 
%   processDTS (GUI), Process_Sensornet and Process_Silixa MATLAB codes.
%
% 	calDTS requires the corresponding calDTS.fig file.
%
% INPUT:
% 	Output file (.mat) from processDTS, Process_Sensornet, or
% 	Process_Silixa.
% 
% 	Required MAT-file Variables:
%         Datetime
%         Distance
%         AntiStokes
%         Stokes
%         Reference Temperatures*
% 
% 	*Reference temperatures from RTDs connected to the DTS system are
% 	automatically detected and parsed when using processDTS,
% 	Process_Sensornet, or Process_Silixa and are usually Tref_1 and
% 	Tref_2.
% 
% 	Additional reference temperatures can be manually added to the
% 	MAT-file using the interp1 command. The matrix dimensions of the
% 	added reference temperature matrix must agree with the dimensions of
% 	the datetime variable. Once the reference temperature
% 	is added the entire workspace must be re-saved.
%
%   For example if the RTD data is copied by columns into two variables
%   rtd_date [1xN] and rtd_temp [1xN] the temperature
% 	could be added by the following command:
%       tref_rtd = interp1(rtd_date', rtd_temp', datetime)
%   NOTE: tref_rtd must be in the form [1xN] for calibration
%         rtd_date and rtd_temp can be cleared/deleted prior to re-saving.
%   
% 	Three point explicit calibration requires 3 reference temperatures.
% 	Three point explicit calibration with a step loss requires 2
% 	reference temperatures.
%
% OUTPUT:
%  	User named MAT-File
%   
%  	Variables:
%       calTemp - calibrated DTS temperatures
%       distance - fiber distance array (from input file)
%       datetime - fiber trace timestamp (from input file)
%       RMSE1, RMSE2, RMSE3 - Root Mean Squared Error (RMSE) for each
%       calibration reference section
%       RMSEavg - average RMSE for all reference points (each reference
%               point is weighted equally).
%       cal_parameters - structure containing calibration parameters
%           and user input.
%           Da, g, and C are calibration parameters
%           z and zVAL are the reference index location used in the calibration
%
% WRITTEN BY: Scott Kobs
% LAST REVISED BY: Scott Kobs, 12/8/2014
%
% ACKNOWLEDGEMENTS:
%   The calibration code utilized in this GUI was originally developed and
%   written by Mark Hausner for CTEMPs.  
%
% REFERENCE:
% Hausner, M. B., F. Suárez, K. E. Glander, N. van de Giesen, J. S. Selker,
%   and S. W. Tyler (2011), Calibrating single-ended fiber-optic Raman
%   spectra distributed temperature sensing data., Sensors (Basel).,
%   11(11), 10859–79, doi:10.3390/s111110859.
%
% See also: processDTS, Process_Sensornet, Process_Silixa, interp1

% Edit the above text to modify the response to help calDTS

% Last Modified by GUIDE v2.5 27-Feb-2018 08:11:46

% Begin initialization code - DO NOT EDIT
gui_Singleton = 1;
gui_State = struct('gui_Name',       mfilename, ...
                   'gui_Singleton',  gui_Singleton, ...
                   'gui_OpeningFcn', @calDTS_OpeningFcn, ...
                   'gui_OutputFcn',  @calDTS_OutputFcn, ...
                   'gui_LayoutFcn',  [] , ...
                   'gui_Callback',   []);
if nargin && ischar(varargin{1})
    gui_State.gui_Callback = str2func(varargin{1});
end

if nargout
    [varargout{1:nargout}] = gui_mainfcn(gui_State, varargin{:});
else
    gui_mainfcn(gui_State, varargin{:});
end

function calDTS_OpeningFcn(hObject, eventdata, handles, varargin)
global dtsGUIglobal
handles.output = hObject;
guidata(hObject, handles);
if isempty(dtsGUIglobal) == 0
    if dtsGUIglobal{1} == 1;
        global PathName FileName
        PathName = dtsGUIglobal{2};
        FileName = dtsGUIglobal{3};    
        load_uidata(hObject,handles)
    end
end
im = imread('diagram.JPG');
imshow(im,'Parent',handles.diagram1);
movegui('northwest');
set(handles.save_button,'Visible','off')
set(handles.review_button,'Visible','off')

function varargout = calDTS_OutputFcn(hObject, eventdata, handles) 
varargout{1} = handles.output;

function load_data_Callback(hObject, eventdata, handles)
global FileName PathName
h = msgbox('Select a MATLAB file containing DTS data to be calibrated.','Single-Ended Calibration','modal');
uiwait(h);
clear h;
[ui_filename, ui_pathname] = uigetfile('*.mat');
if ui_pathname ~= 0;
    FileName = ui_filename;
    PathName = ui_pathname;
    load_uidata(hObject,handles)
end

function load_uidata(hObject,handles)
global tref_drop bathT FileName PathName uidata
handles=guidata(hObject);
uidata = load([PathName FileName]);
flag = 0;
if isfield(uidata,{'datetime','distance', 'tempC','Stokes','AntiStokes'}) == 1
    flag = 1;
end
if flag == 0
    h = msgbox('Insufficient data for calibration','modal');
    uiwait(h);
    uidata = [];
	set(handles.loaded_file,'String','DTS *.mat File:');
    return
end
if length(FileName) > 30
    set(handles.loaded_file,'String',{['DTS *.mat File:   ' FileName(1:30) '...']});
else
    set(handles.loaded_file,'String',{['DTS *.mat File:   ' FileName]});
end
uidata.R=log(uidata.Stokes./uidata.AntiStokes);
traces = numel(uidata.datetime);
if traces ~= 0
    q = fieldnames(uidata);
end
    j=0;
for i = 1:length(q)
    eval(strcat(['num = numel(uidata.', q{i}, ');']));
    if num == traces
        if length(q{i}) == 8
            if q{i} == 'datetime'
                continue
            end
            if q{i} == 'tref_int'
                continue
            end
        elseif length(q{i}) == 15
            if q{i} == 'datetime_offset'
                continue
            end
        end
        j=j+1;
        BathVars{j} = q{i};
    end
end
if j == 0
  	h = msgbox('No reference temperature data found for calibration','','error','modal');
    uiwait(h);
    bathT = [];
    tref_drop = {' '};
else 
    for i=1:j
        eval(strcat(['bathT(i,:) = uidata.', BathVars{i}, ';']));
    end
    clear i j num;
    tref_drop ={1:size(bathT,1)+1};
    tref_drop{1} = ' ';
    for i=2:(size(bathT,1)+1);
        str = ['tref ' num2str(i-1)];
        tref_drop{i} = str;
    end
end
columnformat = {'numeric', 'numeric', tref_drop};
set(handles.ztable, 'ColumnFormat', columnformat);
guidata(hObject,handles)

